DROP TABLE IF EXISTS `comprobante_gasto`;
CREATE TABLE IF NOT EXISTS `comprobante_gasto` (
  `IDComprobanteGasto` int NOT NULL AUTO_INCREMENT,
  `id_pedido` int NOT NULL,
  `id_unidad` int NOT NULL,
  `fecha` date NOT NULL,
  `idproveedor` int DEFAULT NULL,
  `idpresupuesto` int NOT NULL,
  `descripcion` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `concepto` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `id_item` int NOT NULL,
  `preciounit` int NOT NULL,
  `cantidad` int NOT NULL,
  `iva` int NOT NULL,
  `porcentaje_iva` int NOT NULL,
  `exenta` int NOT NULL,
  `gravada` int NOT NULL,
  `id_uni_respon_usu` int NOT NULL,
  `estado` int NOT NULL,
  PRIMARY KEY (`IDComprobanteGasto`),
  KEY `id_unidad` (`id_unidad`),
  KEY `id_uni_respon_usu` (`id_uni_respon_usu`),
  KEY `idproveedor` (`idproveedor`),
  CONSTRAINT `fk_comprobante_proveedor` FOREIGN KEY (`idproveedor`) REFERENCES `proveedores` (`id`),
  CONSTRAINT `fk_comprobante_unidad` FOREIGN KEY (`id_unidad`) REFERENCES `unidad_academica` (`id_unidad`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

